INSERT INTO t_p61016064_digital_innovation_i.glossary_terms
(term, aliases, short_definition, plain_explanation, why_matters, example, category, scope, source, is_verified) VALUES

-- ВНУТРЕННИЙ КОНТРОЛЬ
('Три линии защиты', '3 линии обороны, Three Lines Model', 'Модель распределения ответственности за риски между бизнесом, контролем и аудитом.', 'Первая линия — сам бизнес, который берёт риск и управляет им ежедневно. Вторая линия — подразделения контроля и комплаенса, которые задают правила и следят за их соблюдением. Третья линия — внутренний аудит, который независимо проверяет, работают ли первые две.', 'Это базовая рамка, в которой существует Блок внутреннего контроля. От того, на какой вы линии, зависит объём полномочий и характер ваших функций.', 'Операционист банка проверяет клиента — 1-я линия. Финмониторинг задаёт правила проверки — 2-я линия. Аудит проверяет, соблюдались ли правила — 3-я линия.', 'internal_control', 'global', 'seed', TRUE),

('Комплаенс', 'Compliance, комплаенс-контроль', 'Обеспечение соответствия деятельности банка законам, требованиям регулятора и внутренним нормам.', 'Функция, которая следит, чтобы банк не нарушал правила — законодательство, требования ЦБ, санкционные ограничения, внутренние политики. Работает на предупреждение, а не на наказание постфактум.', 'Комплаенс — соседняя с вами функция внутри Блока. Многие процессы цифровизации затрагивают её напрямую.', 'Проверка контрагента по санкционным спискам перед проведением платежа.', 'internal_control', 'global', 'seed', TRUE),

('ПОД/ФТ', 'AML/CFT, антиотмывочное законодательство, 115-ФЗ', 'Противодействие легализации доходов, полученных преступным путём, и финансированию терроризма.', 'Комплекс требований, обязывающих банк знать своего клиента, отслеживать подозрительные операции и сообщать о них в Росфинмониторинг. Регулируется 115-ФЗ.', 'Это профильная тема ДФМ. Практически вся автоматизация в департаменте так или иначе связана с этими требованиями.', 'Система автоматически помечает операцию как подозрительную, если она подпадает под критерии 115-ФЗ.', 'internal_control', 'global', 'seed', TRUE),

('KYC', 'Know Your Customer, знай своего клиента', 'Процедуры идентификации и изучения клиента перед началом и в ходе обслуживания.', 'Банк обязан установить, кто клиент, чем он занимается, откуда деньги и кто за ним стоит. Это делается при открытии счёта и обновляется регулярно.', 'KYC — один из самых трудоёмких и документоёмких процессов, а значит первый кандидат на автоматизацию и применение AI.', 'Сбор и проверка учредительных документов юрлица при открытии расчётного счёта.', 'internal_control', 'global', 'seed', TRUE),

('Операционный риск', 'Operational risk, опериск', 'Риск потерь из-за сбоев процессов, ошибок людей, отказов систем или внешних событий.', 'Всё, что может пойти не так внутри самого банка: сотрудник ошибся, система упала, процесс не сработал, кто-то смошенничал. Отличается от кредитного и рыночного риска, которые связаны с деньгами клиентов и рынком.', 'Автоматизация напрямую снижает операционный риск — меньше ручных операций, меньше ошибок. Это ваш ключевой аргумент при защите бюджета.', 'Сотрудник вручную перенёс данные из одной системы в другую и ошибся в сумме.', 'internal_control', 'global', 'seed', TRUE),

('Контрольная процедура', 'Контроль, control', 'Конкретное действие, снижающее вероятность или последствия реализации риска.', 'Проверка, сверка, согласование, ограничение доступа, лимит — всё, что встроено в процесс, чтобы риск не реализовался. Бывает превентивной (не даёт случиться) и детективной (обнаруживает постфактум).', 'Когда вы автоматизируете процесс, вы переводите контрольные процедуры из ручных в автоматические. Это главный измеримый эффект.', 'Требование второй подписи на платёж свыше определённой суммы.', 'internal_control', 'global', 'seed', TRUE),

('Матрица рисков и контролей', 'RCM, Risk Control Matrix, РКМ', 'Таблица, связывающая риски процесса с контролями, которые их закрывают.', 'Для каждого процесса выписывают: какие риски есть, какие контроли их закрывают, кто отвечает, как часто проверяется. Сразу видно, где риск есть, а контроля нет.', 'Это готовая карта для приоритизации автоматизации: где контроль ручной и частый — туда идёт робот или AI.', 'В матрице видно, что риск двойной оплаты закрыт только ручной сверкой раз в месяц — кандидат на автоматизацию.', 'internal_control', 'global', 'seed', TRUE),

-- ЦИФРОВИЗАЦИЯ И АВТОМАТИЗАЦИЯ
('RPA', 'Robotic Process Automation, роботизация, робот', 'Программные роботы, повторяющие действия человека в интерфейсах систем.', 'Робот делает то же, что делал сотрудник: открывает систему, копирует данные, вставляет в другую систему, нажимает кнопки. Не требует переделки самих систем — работает поверх них.', 'Самый быстрый способ убрать ручную рутину там, где интеграцию сделать долго или дорого. Типовой первый шаг цифровизации.', 'Робот ежедневно выгружает отчёт из АБС и загружает его в систему отчётности вместо сотрудника.', 'digital', 'global', 'seed', TRUE),

('Оркестрация процессов', 'BPM, Business Process Management, процессный движок', 'Управление сквозным процессом через специальную систему, которая ведёт задачу по этапам.', 'Вместо того чтобы люди пересылали друг другу письма, система сама ведёт заявку по маршруту: назначает исполнителя, следит за сроком, эскалирует просрочку, хранит историю.', 'Даёт прозрачность и измеримость процесса. Без этого невозможно доказать эффект от автоматизации цифрами.', 'Заявка на проверку клиента автоматически проходит этапы: сбор данных → проверка → согласование → решение.', 'digital', 'global', 'seed', TRUE),

('Сквозной процесс', 'End-to-end, E2E процесс', 'Процесс целиком — от первого события до конечного результата, через все подразделения.', 'Обычно каждое подразделение видит только свой кусок. Сквозной взгляд показывает весь путь: где задержки, где данные вводят повторно, где решения дублируются.', 'Автоматизация куска даёт мало эффекта. Настоящая экономия появляется, когда оптимизируют весь путь.', 'От поступления платежа до финального решения по нему — через 4 подразделения и 3 системы.', 'digital', 'global', 'seed', TRUE),

('Цифровой двойник процесса', 'Process Digital Twin', 'Электронная модель процесса, отражающая его реальное состояние и позволяющая моделировать изменения.', 'Процесс описан в системе так подробно, что можно проиграть сценарий: а что будет, если убрать этот шаг или добавить робота. Без риска для реальной работы.', 'Позволяет обосновать решение до вложения денег — сильный аргумент в бюджетной защите.', 'Моделируем: если автоматизировать 2 из 7 шагов, срок обработки упадёт с 5 дней до 2.', 'digital', 'global', 'seed', TRUE),

('Process Mining', 'Процессная аналитика, майнинг процессов', 'Восстановление реальной картины процесса по логам информационных систем.', 'Система читает следы в логах и рисует, как процесс идёт на самом деле — а не как он описан в регламенте. Обычно разница большая.', 'Даёт объективные данные вместо мнений: где реально узкие места и сколько времени теряется. Это фактура для бюджета.', 'Регламент говорит 3 дня, а майнинг показывает средний срок 11 дней и 40% возвратов на доработку.', 'digital', 'global', 'seed', TRUE),

('Легаси', 'Legacy, легаси-система, унаследованная система', 'Устаревшая система, которую сложно менять, но нельзя выключить.', 'Работает годами, на ней держатся ключевые операции, но она написана давно, поддержка дорогая, интеграции ограничены. Заменить страшно и дорого.', 'Легаси — главное ограничение любого плана цифровизации. Его нужно честно учитывать в сроках и бюджете.', 'Основная банковская система, к которой нельзя быстро прикрутить новый сервис.', 'digital', 'global', 'seed', TRUE),

-- ИСКУССТВЕННЫЙ ИНТЕЛЛЕКТ
('LLM', 'Большая языковая модель, Large Language Model, ГПТ', 'Модель ИИ, обученная работать с текстом: понимать, обобщать, генерировать.', 'Тип ИИ, который хорошо работает с текстами и документами: пересказать, найти нужное, сравнить с требованием, составить черновик. Не считает и не гарантирует точность — проверяет человек.', 'Для вашей области это ключевая технология: внутренний контроль работает с огромным объёмом документов и регламентов.', 'Модель сравнивает договор с чек-листом требований и отмечает расхождения.', 'ai', 'global', 'seed', TRUE),

('RAG', 'Retrieval-Augmented Generation, поиск с генерацией', 'Подход, при котором ИИ отвечает строго на основе загруженных документов, а не общих знаний.', 'Сначала система находит нужные фрагменты в ваших документах, потом на их основе формирует ответ со ссылками на источник. Резко снижает выдумывание.', 'Единственный приемлемый способ применять ИИ там, где важна достоверность и нужно показать источник — то есть в контроле.', 'Вопрос «какие требования к идентификации клиента» — ответ со ссылкой на пункт вашего внутреннего положения.', 'ai', 'global', 'seed', TRUE),

('Галлюцинация ИИ', 'Hallucination, выдумывание', 'Ситуация, когда модель уверенно выдаёт неверную информацию.', 'Модель не знает, что она не знает. Если данных нет, она может правдоподобно придумать — с виду убедительно, по сути неверно.', 'Главный риск ИИ в банке. Именно поэтому в контроле нужны ссылки на источник и обязательная проверка человеком.', 'Модель называет несуществующий пункт нормативного акта.', 'ai', 'global', 'seed', TRUE),

('Human-in-the-loop', 'HITL, человек в контуре', 'Схема, при которой решение ИИ обязательно подтверждается человеком.', 'ИИ готовит и предлагает, человек проверяет и утверждает. Ответственность остаётся на человеке, скорость растёт за счёт подготовки.', 'Для внутреннего контроля это обязательное условие: полностью автономный ИИ в контрольных решениях не проходит по риску.', 'ИИ отбирает 20 подозрительных операций из 10 000, аналитик проверяет только их.', 'ai', 'global', 'seed', TRUE),

('Объяснимость модели', 'Explainability, XAI, интерпретируемость', 'Возможность понять, почему модель приняла такое решение.', 'Если модель отклонила операцию, должно быть видно, на каких признаках она основывалась. Иначе решение невозможно обосновать ни клиенту, ни регулятору.', 'Для банка это требование не техническое, а регуляторное. Без объяснимости модель не допустят в контрольный контур.', 'Модель показывает: операция помечена из-за суммы, страны и нетипичного времени.', 'ai', 'global', 'seed', TRUE),

-- УПРАВЛЕНИЕ И БЮДЖЕТ
('CAPEX / OPEX', 'Капитальные и операционные затраты, капекс, опекс', 'Два типа расходов: вложения в актив и текущие затраты на работу.', 'CAPEX — разовые вложения, которые ставятся на баланс и списываются годами: закупка лицензий, разработка системы. OPEX — регулярные расходы: подписка, поддержка, зарплаты.', 'При бюджетировании крайне важно правильно разнести затраты — от этого зависит и одобрение, и нагрузка на финансовый результат.', 'Покупка платформы — CAPEX. Ежемесячная подписка на облачный сервис — OPEX.', 'budget', 'global', 'seed', TRUE),

('TCO', 'Total Cost of Ownership, совокупная стоимость владения', 'Полная стоимость решения за весь срок жизни, а не только цена покупки.', 'Помимо покупки: внедрение, интеграция, обучение, поддержка, доработки, вывод из эксплуатации. Часто покупка — это меньшая часть суммы.', 'Бюджет на 2027 защищается именно по TCO. Если показать только цену лицензии, дальше пойдут незапланированные расходы.', 'Лицензия 10 млн, но с внедрением и трёхлетней поддержкой выходит 28 млн.', 'budget', 'global', 'seed', TRUE),

('ROI', 'Return on Investment, окупаемость, возврат инвестиций', 'Отношение полученного эффекта к вложенным средствам.', 'Показывает, окупились ли вложения и насколько. Считается как эффект минус затраты, делённое на затраты.', 'Основной вопрос на бюджетном комитете. Для автоматизации эффект считают через высвобожденные часы, снижение потерь и ошибок.', 'Вложили 12 млн, экономия 8 млн в год — окупаемость около полутора лет.', 'budget', 'global', 'seed', TRUE),

('FTE', 'Full-Time Equivalent, эквивалент полной занятости, штатная единица', 'Единица измерения трудозатрат, равная одному сотруднику на полной ставке.', 'Позволяет считать не людей, а объём работы. Если пять человек тратят по 20% времени на задачу — это 1 FTE.', 'Ключевая метрика обоснования автоматизации: «высвобождаем 3,5 FTE» звучит для финансистов конкретнее, чем «станет удобнее».', 'Ручная сверка отнимает 2,4 FTE в год — после робота 0,3 FTE.', 'budget', 'global', 'seed', TRUE),

('Бизнес-кейс', 'Business case, обоснование инициативы', 'Документ, обосновывающий вложение: проблема, решение, затраты, эффект, риски.', 'Отвечает на вопросы: какую проблему решаем, сколько стоит, что получим, за какой срок окупится, что будет, если не делать.', 'Это основной формат защиты бюджета 2027. Инициатива без бизнес-кейса на комитете практически не проходит.', 'Кейс на внедрение робота: проблема 2,4 FTE ручной работы, вложения 4 млн, эффект 6 млн в год.', 'budget', 'global', 'seed', TRUE),

('Дорожная карта', 'Roadmap, роадмап', 'План развития по времени: что и когда делаем, с вехами и зависимостями.', 'Показывает последовательность: что сначала, что потом, что от чего зависит. Обычно горизонтами — ближайший квартал детально, дальше крупными блоками.', 'Бюджет утверждается под дорожную карту. Без неё непонятно, за что именно платят в каждом квартале.', 'Q1 — пилот на одном процессе, Q2 — тираж на управление, Q3 — расширение.', 'budget', 'global', 'seed', TRUE),

-- ПРОЕКТНОЕ УПРАВЛЕНИЕ
('MVP', 'Minimum Viable Product, минимально жизнеспособный продукт', 'Самая простая рабочая версия, на которой можно проверить гипотезу.', 'Не урезанный продукт, а минимум, достаточный чтобы понять — работает идея или нет. Делается быстро и дёшево, до больших вложений.', 'Позволяет просить в бюджете небольшую сумму на проверку, а не сразу крупную на полномасштабное внедрение.', 'Робот на один участок вместо автоматизации всего департамента сразу.', 'management', 'global', 'seed', TRUE),

('Пилот', 'Пилотный проект, PoC, Proof of Concept', 'Ограниченное по масштабу внедрение для проверки решения в реальных условиях.', 'Проверяем на одном подразделении или одном процессе: работает ли технология, даёт ли эффект, что мешает. Потом решаем про тираж.', 'Пилот снижает риск крупных вложений и даёт фактуру для бюджетной защиты следующего года.', 'Пилот AI-помощника на одном управлении в течение квартала.', 'management', 'global', 'seed', TRUE),

('Тиражирование', 'Масштабирование, раскатка, scale-up', 'Распространение проверенного на пилоте решения на остальные подразделения.', 'После успешного пилота решение внедряют шире. Обычно требует больше денег, но риск уже понятен.', 'Тираж — самая дорогая стадия. Её нужно закладывать в бюджет отдельно от пилота.', 'После пилота на одном управлении раскатываем на весь департамент.', 'management', 'global', 'seed', TRUE),

('Стейкхолдер', 'Stakeholder, заинтересованная сторона', 'Человек или подразделение, чьи интересы затрагивает ваш проект.', 'Тот, кто влияет на проект или на кого проект влияет: заказчик, пользователи, ИТ, безопасность, финансы, регулятор.', 'Проекты цифровизации чаще срываются из-за несогласованности стейкхолдеров, чем из-за технологий.', 'Для автоматизации ДФМ стейкхолдеры — само подразделение, ИТ, ИБ, комплаенс и финансы.', 'management', 'global', 'seed', TRUE),

('Владелец процесса', 'Process owner, оунер', 'Руководитель, отвечающий за результат и развитие конкретного процесса.', 'Не тот, кто выполняет, а тот, кто отвечает за то, чтобы процесс работал и улучшался. Принимает решения об изменениях.', 'Без назначенного владельца изменения в процессе буксуют — некому принять решение и защитить его.', 'Владелец процесса проверки клиентов согласовывает изменение маршрута заявки.', 'management', 'global', 'seed', TRUE),

('Квик-вин', 'Quick win, быстрая победа', 'Небольшое улучшение с быстрым и заметным эффектом.', 'Делается за недели, а не месяцы, требует мало ресурсов, но эффект виден сразу. Строит доверие к более крупным инициативам.', 'В начале в новой должности квик-вины особенно важны — они дают вам кредит доверия на большие проекты.', 'Убрать двойной ввод данных между двумя отчётами — неделя работы, минус 0,3 FTE.', 'management', 'global', 'seed', TRUE),

-- ФУНКЦИИ И ДОЛЖНОСТИ
('Профессиональный стандарт', 'Профстандарт', 'Утверждённый документ с требованиями к квалификации по виду профессиональной деятельности.', 'Описывает, какие трудовые функции входят в профессию, какие действия, знания и умения нужны. Утверждается Минтрудом и имеет структуру: обобщённые трудовые функции → трудовые функции → трудовые действия.', 'Формулировки должностной инструкции и положения о подразделении корректнее строить на профстандарте — тогда они защищены от вопросов кадров и проверок.', 'Профстандарт специалиста по финансовому мониторингу описывает трудовые функции по выявлению подозрительных операций.', 'roles', 'global', 'seed', TRUE),

('Обобщённая трудовая функция', 'ОТФ', 'Крупный блок трудовых функций в профстандарте, соответствующий определённому уровню квалификации.', 'Верхний уровень структуры профстандарта. Обозначается буквой (A, B, C) и привязан к уровню квалификации. Внутри содержит конкретные трудовые функции.', 'Для руководящей должности берут ОТФ более высокого уровня квалификации — это основание для грейда и требований к образованию.', 'ОТФ «Руководство деятельностью по внутреннему контролю» уровня квалификации 7.', 'roles', 'global', 'seed', TRUE),

